          "n": 1,
          "text": "२ अज्ञानो.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r13",
      "type": "footnote",
      "lines": [
        {
          "n": 1,
          "text": "३ अङ्गेषु भाषितम्.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    }
